CREATE SCHEMA IF NOT EXISTS workspace.bricksmart;

CREATE OR REPLACE TABLE workspace.bricksmart.sales (
  order_line_id          STRING NOT NULL,
  order_id               STRING NOT NULL,
  order_datetime         TIMESTAMP,
  quantity               INT,
  unit_price             INT,
  line_total             INT,
  channel                STRING,
  device                 STRING,
  product_id             STRING,
  product_name           STRING,
  major_category         STRING,
  minor_category         STRING,
  customer_id            STRING,
  customer_last_name     STRING,
  gender                 STRING,
  age                    INT,
  prefecture             STRING,
  register_date          DATE,
  churn_date             DATE,
  acquisition_channel    STRING,
  total_orders           INT,
  total_spent            DOUBLE,
  first_month_orders     INT,
  loyalty_tier           STRING
) USING DELTA;








































